-- The 5 national cups of worldVersion 2 saves, one per country: no club, no player, their ties are drawn in the game.
-- Generated by scripts/generate-reference-migration.ts from the seed (prisma/seed/competitions.ts), never edited by hand:
-- prisma/seed/reference-sql.test.ts checks it against the generator. Idempotent, on the competition's code.
INSERT INTO "Competition" ("id", "code", "name", "country", "tier", "kind")
SELECT gen_random_uuid()::text, v.code, v.name, v.country, v.tier, 'CUP'::"CompetitionKind"
FROM (VALUES
  ('en.cup', 'Angleterre — Coupe', 'Angleterre', 0),
  ('es.cup', 'Espagne — Coupe', 'Espagne', 0),
  ('de.cup', 'Allemagne — Coupe', 'Allemagne', 0),
  ('it.cup', 'Italie — Coupe', 'Italie', 0),
  ('fr.cup', 'France — Coupe', 'France', 0)
) AS v (code, name, country, tier)
ON CONFLICT ("code") DO NOTHING;
